const rank=c=>(c%13+12)%13;
const suit=c=>[1,0,2,3][Math.floor(c/13)];
const strength=c=>rank(c)*4+suit(c);
const opening=14;
function score(cards) {
  const sorted=[...cards].sort((a,b)=>strength(a)-strength(b));
  const high=sorted[sorted.length-1];
  const groups=Array.from({length:13},(_,r)=>sorted.filter(c=>rank(c)===r));
  if([1,2,3].includes(cards.length))
    return groups.some(g=>g.length===cards.length)?strength(high):-1;
  if(cards.length!==5)return -1;
  const ranks=sorted.map(rank);
  const flush=sorted.every(c=>suit(c)===suit(high));
  const straightHigh=ranks.join(",")==="0,1,2,11,12"?2:ranks.join(",")==="0,1,2,3,12"?3:
    ranks[4]<12&&ranks.every((r,i)=>r===ranks[0]+i)?ranks[4]:-1;
  const straightValue=straightHigh*4+suit(sorted.find(c=>rank(c)===straightHigh));
  if(flush&&straightHigh>=0)return 500+straightValue;
  const four=groups.findIndex(g=>g.length===4);
  if(four>=0)return 400+four;
  const three=groups.findIndex(g=>g.length===3);
  if(three>=0&&groups.some(g=>g.length===2))return 300+three;
  if(flush)return 200+suit(high)*16+rank(high);
  return straightHigh>=0?100+straightValue:-1;
}
function allowed(s,cards) {
  if(!Array.isArray(cards)||!cards.length||new Set(cards).size!==cards.length||
    !cards.every(c=>s.hands[s.seat].includes(c))||s.open&&!cards.includes(opening))return false;
  const value=score(cards);
  return value>=0&&(!s.table.length||s.table.length===cards.length&&value>score(s.table));
}
function moves(s) {
  const hand=s.hands[s.seat],options=[];
  const search=(selection,start,size)=>{
    if(selection.length===size){if(allowed(s,selection))options.push({cards:selection});return;}
    for(let i=start;i<=hand.length-(size-selection.length);i++)search([...selection,hand[i]],i+1,size);
  };
  for(const size of s.table.length?[s.table.length]:[1,2,3,5])search([],0,size);
  if(s.table.length)options.push({pass:true});
  return options;
}
const game={
  newMatch(ctx){
    let seed=2166136261;
    for(const p of ctx.players)for(const c of p.id)seed=Math.imul(seed^c.charCodeAt(0),16777619);
    const deck=Array.from({length:52},(_,i)=>i);
    for(let i=deck.length-1;i>0;i--){
      seed=(Math.imul(seed,1664525)+1013904223)>>>0;
      const j=seed%(i+1);
      [deck[i],deck[j]]=[deck[j],deck[i]];
    }
    const hands=ctx.players.map((_,i)=>deck.slice(i*13,i*13+13).sort((a,b)=>strength(a)-strength(b)));
    const seat=hands.findIndex(h=>h.includes(opening));
    return {state:{hands,seat,leader:seat,passes:0,table:[],open:true,winners:[]},turn:[ctx.players[seat].id]};
  },
  applyMove(s,id,m,ctx){
    if(!m||Object.keys(m).length!==1||ctx.players[s.seat].id!==id||s.winners.length||
      !(m.pass===true?s.table.length:allowed(s,m.cards)))
      throw new InvalidMove("Choose a legal move on your turn.");
    const state={...s,seat:(s.seat+1)%4};
    if(m.pass){
      state.passes++;
      if(state.passes===3){state.table=[];state.passes=0;state.seat=s.leader;}
    }else{
      state.hands=s.hands.map((hand,i)=>i===s.seat?hand.filter(c=>!m.cards.includes(c)):hand);
      state.table=[...m.cards];
      state.leader=s.seat;
      state.passes=0;
      state.open=false;
      if(!state.hands[s.seat].length){
        state.winners=[s.seat];
        const humans=ctx.players.filter(p=>p.kind==="human"&&p.active!==false);
        const winner=ctx.players[s.seat];
        const paid=humans.includes(winner)?[winner]:humans;
        return {state,turn:null,payouts:Object.fromEntries(paid.map((p,i)=>[p.id,
          Math.floor(ctx.pot/paid.length)+Number(i<ctx.pot%paid.length)]))};
      }
    }
    return {state,turn:[ctx.players[state.seat].id]};
  },
  viewFor(s,id,ctx){
    const {hands,...visible}=s;
    const i=ctx.players.findIndex(p=>p.id===id);
    return {...visible,hand:hands[i]??[],counts:hands.map(h=>h.length)};
  },
  computerMove(s){
    return moves(s).sort((a,b)=>(b.cards?.length??0)-(a.cards?.length??0)||
      (a.cards&&b.cards?score(a.cards)-score(b.cards):0))[0];
  },
  randomMove(s,id,ctx){
    const options=moves(s);
    return options[Math.floor(ctx.random()*options.length)];
  }
};

